    name: &'static str,
    block_has: &'static [&'static str],
    block_lacks: &'static [&'static str],
    allow_has: &'static [&'static str],
    allow_lacks: &'static [&'static str],
    stream_failure: bool,
}

const fn row(
    name: &'static str,
    block_has: &'static [&'static str],
    block_lacks: &'static [&'static str],
    allow_has: &'static [&'static str],
    allow_lacks: &'static [&'static str],
    stream_failure: bool,
) -> Row {
    Row {
        name,
        block_has,
        block_lacks,
        allow_has,
        allow_lacks,
        stream_failure,
    }
}

